CREATE FUNCTION public.capsule_audio_access(_path text,_write boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR split_part(_path,'/',1)<>auth.uid()::text THEN RETURN false; END IF; IF _write THEN RETURN EXISTS(SELECT 1 FROM season_entries WHERE user_id=auth.uid() AND season_id::text=split_part(_path,'/',2)) AND NOT EXISTS(SELECT 1 FROM capsules WHERE user_id=auth.uid() AND season_id::text=split_part(_path,'/',2)); END IF; RETURN EXISTS(SELECT 1 FROM capsules WHERE user_id=auth.uid() AND audio_url=_path AND _local_today(auth.uid())>=opens_on);END $$;
REVOKE ALL ON FUNCTION public.capsule_audio_access(text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.capsule_audio_access(text,boolean) TO authenticated,service_role;
ALTER POLICY capsule_audio_insert ON storage.objects WITH CHECK(bucket_id='capsule-audio' AND public.capsule_audio_access(name,true));
ALTER POLICY capsule_audio_read ON storage.objects USING(bucket_id='capsule-audio' AND public.capsule_audio_access(name,false));
ALTER POLICY capsule_audio_delete ON storage.objects USING(bucket_id='capsule-audio' AND public.capsule_audio_access(name,true));
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.admin_clear_demo()'::regprocedure) INTO f;f:=replace(f,'''announcement_receipts'',''announcements''','''day_closes'',''capsules'',''moments_seen'',''moment_reminders'',''announcement_receipts'',''announcements''');EXECUTE f; END $$;